// z8000_decode -- instruction decode: (w0, w1[3:0]) -> ctrl_word_t.
//
// The ROM is generated: rtl/k800x_cpu/gen/z8000_decode_rom_gen.sv is
// regenerated by `make gen`. A hand-structured decoder (a 5-stage PLA
// split) can replace the flat table here later -- tb/k800x_cpu/tb_decode.sv
// must still pass against vectors/k800x_cpu/decode/decode.vec (all 65536 first words x the w1 nibble where it
// matters). An instruction's length is its machine-cycle program's, not
// the decoder's.
//
// STATUS: complete via the generated table (passes tb_decode).

module z8000_decode
  import z8000_ctrl_pkg::*;
(
  input  logic [15:0] w0,
  input  logic [3:0]  w1_lo,
  output ctrl_word_t  ctrl
);

  z8000_decode_rom_gen u_rom (
    .w0    (w0),
    .w1_lo (w1_lo),
    .ctrl  (ctrl)
  );

endmodule
